{
  "contract": "WuZeTian",
  "closure": {
    "site_function": "addLiquidity",
    "site_call": ".call",
    "functions": [
      "addLiquidity",
      "transfer",
      "transferFrom",
      "approve",
      "setExempt",
      "setFees",
      "setFeeSplit",
      "updateWallets",
      "setLimits",
      "setTaxSwap"
    ],
    "justification": "Includes all functions that can affect _balances, _inTaxSwap, _isLP, and _primaryLP, which are exposed during the risky call."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "transfer",
      "transferFrom",
      "approve",
      "setExempt",
      "setFees",
      "setFeeSplit",
      "updateWallets",
      "setLimits",
      "setTaxSwap"
    ],
    "nesting_bound": {
      "transfer": 1,
      "transferFrom": 1,
      "approve": 1,
      "setExempt": 1,
      "setFees": 1,
      "setFeeSplit": 1,
      "updateWallets": 1,
      "setLimits": 1,
      "setTaxSwap": 1
    }
  },
  "phases": {
    "function": "addLiquidity",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Tracks the amount of tokens in flight during the callback window.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum__balances + _swapLimit == _totalSupply + inFlight",
    "stable_formula": "_sum__balances + _swapLimit == _totalSupply",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum__balances + _swapLimit == _totalSupply",
    "rule": "The sum of balances and swap limit must equal the total supply, accounting for in-flight tokens during reentrancy."
  }
}
